@import "tailwindcss";
@import "@fontsource-variable/geist";
@import "@fontsource/instrument-serif";
@import "@fontsource/instrument-serif/400-italic.css";

@source "./**/*.{ts,tsx}";

@theme {
  --color-ink: #0e0a11;
  --color-ink-soft: #171019;
  --color-ink-card: #1c141f;
  --color-cream: #f7f0e8;
  --color-ember: #ff7a45;
  --color-ember-soft: #ffc9a3;
  --color-dusk: #b98ba5;
  --font-display: "Instrument Serif", Georgia, serif;
  --font-sans: "Geist Variable", system-ui, sans-serif;
}

:root {
  font-family: "Geist Variable", system-ui, sans-serif;
  color: #f7f0e8;
  background: #0e0a11;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

* {
  box-sizing: border-box;
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: #0e0a11;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: rgba(255, 122, 69, 0.35);
  color: #f7f0e8;
}

:focus-visible {
  outline: 2px solid #ff7a45;
  outline-offset: 3px;
  border-radius: 2px;
}

.landing-page {
  position: relative;
  overflow: hidden;
  background: #0e0a11;
  color: #f7f0e8;
}

/* Film grain over the whole page */
.landing-page::before {
  position: fixed;
  z-index: 40;
  inset: 0;
  pointer-events: none;
  content: "";
  opacity: 0.05;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
}

.landing-page > * {
  position: relative;
  z-index: 1;
}

/* Scroll reveal */
.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition:
    opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}

.reveal.is-visible {
  opacity: 1;
  transform: none;
}

/* Slow cinematic push-in on hero imagery */
@keyframes hero-zoom {
  from {
    transform: scale(1.12);
  }
  to {
    transform: scale(1);
  }
}

.hero-zoom {
  animation: hero-zoom 14s cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* Gentle float for the phone mock */
@keyframes float-slow {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-12px);
  }
}

.float-slow {
  animation: float-slow 7s ease-in-out infinite;
}

/* Scroll cue line */
@keyframes cue-drop {
  0% {
    transform: scaleY(0);
    transform-origin: top;
  }
  45% {
    transform: scaleY(1);
    transform-origin: top;
  }
  55% {
    transform: scaleY(1);
    transform-origin: bottom;
  }
  100% {
    transform: scaleY(0);
    transform-origin: bottom;
  }
}

.cue-line {
  animation: cue-drop 2.2s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .hero-zoom,
  .float-slow,
  .cue-line {
    animation: none;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

