import { Reveal } from "./reveal";

const TIERS = [
  {
    name: "Free",
    id: "tier-free",
    href: "/signin?intent=signup",
    price: "$0",
    priceNote: "forever",
    description: "Everything you need to feel the agent work.",
    features: [
      "Up to 20 bookmarks",
      "20 agent runs each month",
      "10 chat questions each month",
      "Browser extension",
      "iOS app",
    ],
