    featured: false,
  },
  {
    name: "Pro",
    id: "tier-pro",
    href: "/upgrade",
    price: "$5",
    priceNote: "per month, billed annually",
    description: "For a library that grows every single day.",
    features: [
      "Up to 50,000 bookmarks",
